mapper.select:
with src (id, account_id, goodfish_account_id, goodfish_item_id, title, description, price, stock_status, image_url, sync_time) as ( values
(#{it.id}, #{it.accountId}, #{it.goodfishAccountId}, #{it.goodfishItemId}, #{it.title}, #{it.description}, #{it.price}, #{it.stockStatus}, #{it.imageUrl}, #{it.syncTime})
), prev as ( select i.goodfish_item_id, i.title, i.description, i.price, i.stock_status, i.image_url, i.del_flag from goodfish_item i join src s on s.goodfish_item_id = i.goodfish_item_id where i.goodfish_account_id = #{entities[0].goodfishAccountId} ), ins as ( insert into goodfish_item (id, account_id, goodfish_account_id, goodfish_item_id, title, description, price, stock_status, image_url, sync_time, del_flag) select id, account_id, goodfish_account_id, goodfish_item_id, title, description, price, stock_status, image_url, sync_time, '0' from src on conflict (goodfish_account_id, goodfish_item_id) do update set account_id = excluded.account_id, title = excluded.title, description = excluded.description, price = excluded.price, stock_status = excluded.stock_status, image_url = excluded.image_url, sync_time = excluded.sync_time, del_flag = '0', update_time = now() returning goodfish_item_id, (xmax = 0) as inserted ) select count(*) filter (where ins.inserted) as "insertedCount", count(*) filter (where not ins.inserted and ( p.goodfish_item_id is null or (p.title, p.description, p.price, p.stock_status, p.image_url, p.del_flag) is distinct from (s.title, s.description, s.price, s.stock_status, s.image_url, '0') )) as "updatedCount", count(*) filter (where not ins.inserted and p.goodfish_item_id is not null and not ( (p.title, p.description, p.price, p.stock_status, p.image_url, p.del_flag) is distinct from (s.title, s.description, s.price, s.stock_status, s.image_url, '0') )) as "unchangedCount" from ins join src s on s.goodfish_item_id = ins.goodfish_item_id left join prev p on p.goodfish_item_id = ins.goodfish_item_id
